        "role": "user",
        "content": user_input,
    }
)

for step in range(self.max_steps):
    self._log(f"\n--- STEP {step} ---")
    self._print_memory()

    llm = self.session_manager.get_active_provider()

self.memory.append(
    {
        "role": "assistant",
        "content": None,
        "tool_calls": [
            {
                "id": tool_call_id,
                "type": "function",
                "function": {
                    "name": tool_name,
                    "arguments": args or {},
                },
            }
        ],
    }
)

# Execute the tool
tool = self.tools.get(tool_name)
if not tool:
    result = f"[TOOL ERROR] Unknown tool: {tool_name}"
else:
    try:
        result = tool.run(**args)
    except Exception as e:
        result = f"[TOOL ERROR] {str(e)}"

self._log(f"TOOL [{tool_name}] RESULT:", result)

# Record tool result in canonical format (ADR-005)
self.memory.append(
    {
        "role": "tool",
        "tool_call_id": tool_call_id,
        "content": str(result),
    }
)

if self.tool_call_count % self.auto_prune_after == 0:
    self.prune_memory()

continue

